floyd class Solution {
public:
int findTheCity(int n, vector<vector>& edges, int distanceThreshold) {
vector<vector> grid(n, vector(n, 10005));  // 因为边的最大距离是10^4     // 节点到自己的距离为0
    for (int i = 0; i < n; i++) grid[i][i] = 0;
    // 构造邻接矩阵
    for (const vector<int>& e : edges) {
        int from = e[0];
        int to = e[1];
        int val = e[2];
        grid[from][to] = val;
        grid[to][from] = val; // 注意这里是双向图
    }

    // 开始 floyd
    // 思考 为什么 p 要放在最外面一层
    for (int p = 0; p < n; p++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                grid[i][j] = min(grid[i][j], grid[i][p] + grid[p][j]);
            }
        }
    }

    int result = 0;
    int count = n + 10; // 记录所有城市在范围内连接的最小城市数量
    for (int i = 0; i < n; i++) {
        int curCount = 0; // 统计一个城市在范围内可以连接几个城市
        for (int j = 0; j < n; j++) {
            if (i != j && grid[i][j] <= distanceThreshold) curCount++;
            // cout << "i:" << i << ", j:" << j << ", val: " << grid[i][j] << endl;
        }
        if (curCount <= count) { // 注意这里是 <=
            count = curCount;
            result = i;
        }
    }
    return result;
}
};

题目链接  本题思路就是统计各个节点的度（这里没有区别入度和出度），如果某个节点的度等于这个图边的数量。 那么这个节点一定是中心节点。 什么是度，可以理解为，链接节点的边的数量。 题目中度如图所示：  至于出度和入度，那就是在有向图里的概念了，本题是无向图。 本题代码如下： 
class Solution {
public:
    int findCenter(vector<vector<int>>& edges) {
        unordered_map<int ,int> du;
        for (int i = 0; i < edges.size(); i++) { // 统计各个节点的度    
                du[edges[i][1]]++;
                du[edges[i][0]]++;
        }
        unordered_map<int, int>::iterator iter;  // 找出度等于边熟练的节点
        for (iter = du.begin(); iter != du.end(); iter++) { 
            if (iter->second == edges.size()) return iter->first;
        }
        return -1;
    }
};
